-- Finance Chat memory and audit tables for Databricks (Delta, Unity Catalog)
-- Target: lakehouse_mvpai.aiops  (change the catalog/schema below if different)
-- Five tables. Tables are prefixed finance_chat_ because the aiops schema is shared.
-- NOT TESTED on Databricks: run each statement in a notebook or SQL editor and fix any error.
--
-- Notes
--  * IDs are UUID strings generated by the app.
--  * Enums are STRING columns with CHECK constraints (Delta has no ENUM type).
--  * PRIMARY KEY is informational only in Unity Catalog (not enforced). The app must not
--    insert duplicates: write with MERGE on the key, not blind INSERT.
--  * No defaults are used: the app sets every value, including created_at and status.
--  * Foreign keys are not declared (informational only); relations are described in comments.
--  * Liquid clustering (CLUSTER BY) replaces indexes.

-- ---------------------------------------------------------------------------
-- 1. Conversations
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS lakehouse_mvpai.aiops.finance_chat_conversations (
  conversation_id       STRING    NOT NULL COMMENT 'UUID',
  user_id               STRING    NOT NULL COMMENT 'From SSO, UUID or object id',
  title                 STRING    COMMENT 'Short title from the first question',
  domain                STRING    COMMENT 'e.g. fa, ap, gl',
  visibility            STRING    NOT NULL COMMENT 'visible | hidden | deleted',
  turn_count            INT       NOT NULL,
  summary               STRING    COMMENT 'Rolling summary written by the memory worker',
  summary_through_turn  INT       NOT NULL COMMENT 'Last turn_index included in summary',
  summary_updated_at    TIMESTAMP,
  created_at            TIMESTAMP NOT NULL,
  last_message_at       TIMESTAMP NOT NULL,
  context_start_turn    INT       COMMENT 'Turns up to this index are ignored as context (clear context)',
  CONSTRAINT pk_finance_chat_conversations PRIMARY KEY (conversation_id)
)
USING DELTA
CLUSTER BY (user_id, last_message_at)
COMMENT 'One row per conversation'
TBLPROPERTIES (
  'delta.autoOptimize.optimizeWrite' = 'true',
  'delta.autoOptimize.autoCompact'   = 'true'
);

ALTER TABLE lakehouse_mvpai.aiops.finance_chat_conversations
  ADD CONSTRAINT chk_conv_visibility CHECK (visibility IN ('visible', 'hidden', 'deleted'));

-- ---------------------------------------------------------------------------
-- 2. Messages: one row per user question and its answer
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS lakehouse_mvpai.aiops.finance_chat_messages (
  message_id            STRING    NOT NULL COMMENT 'The question UUID',
  conversation_id       STRING    NOT NULL COMMENT 'Refers to finance_chat_conversations',
  user_id               STRING    NOT NULL,
  turn_index            INT       NOT NULL COMMENT '1, 2, 3 ... within the conversation',

  question_text         STRING    NOT NULL COMMENT 'As typed by the user',
  standalone_question   STRING    COMMENT 'Follow-up rewritten in full by the planner',
  intent                STRING    COMMENT 'metric | list | clarify | denied',
  answer_path           STRING    COMMENT 'kpi | adhoc | clarify | declined',
  domain                STRING,
  kpi_ids               ARRAY<STRING> COMMENT 'Approved KPIs used',
  plan                  STRING    COMMENT 'Planner JSON after verification',

  sql_text              STRING    COMMENT 'Final SQL executed',
  sql_source            STRING    COMMENT 'compiled | generated',
  result_row_count      INT,
  result_preview        STRING    COMMENT 'JSON, first rows only, capped',

  answer_text           STRING,
  trust_label           STRING    COMMENT 'Finance-approved | Validated | Matches gold | Unverified',
  clarification_text    STRING,

  status                STRING    NOT NULL COMMENT 'processing | answered | clarification | declined | failed',
  visibility            STRING    NOT NULL COMMENT 'visible | hidden | deleted',
  hidden_reason         STRING,
  error_code            STRING,
  error_message         STRING,
  retry_count           SMALLINT  NOT NULL,

  llm_call_count        SMALLINT  NOT NULL,
  input_tokens          INT       NOT NULL,
  output_tokens         INT       NOT NULL,
  models_used           ARRAY<STRING>,
  first_token_ms        INT,
  total_latency_ms      INT,

  created_at            TIMESTAMP NOT NULL,
  completed_at          TIMESTAMP,
  CONSTRAINT pk_finance_chat_messages PRIMARY KEY (message_id)
)
USING DELTA
CLUSTER BY (user_id, created_at)
COMMENT 'One row per question. Unique (conversation_id, turn_index) is enforced by the app.'
TBLPROPERTIES (
  'delta.autoOptimize.optimizeWrite' = 'true',
  'delta.autoOptimize.autoCompact'   = 'true'
);

ALTER TABLE lakehouse_mvpai.aiops.finance_chat_messages
  ADD CONSTRAINT chk_msg_status CHECK (status IN ('processing', 'answered', 'clarification', 'declined', 'failed'));
ALTER TABLE lakehouse_mvpai.aiops.finance_chat_messages
  ADD CONSTRAINT chk_msg_visibility CHECK (visibility IN ('visible', 'hidden', 'deleted'));
ALTER TABLE lakehouse_mvpai.aiops.finance_chat_messages
  ADD CONSTRAINT chk_msg_answer_path CHECK (answer_path IS NULL OR answer_path IN ('kpi', 'adhoc', 'clarify', 'declined'));

-- ---------------------------------------------------------------------------
-- 3. Message events: one row per graph step per question
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS lakehouse_mvpai.aiops.finance_chat_message_events (
  event_id              STRING    NOT NULL COMMENT 'UUID',
  message_id            STRING    NOT NULL COMMENT 'Refers to finance_chat_messages',
  conversation_id       STRING    NOT NULL,
  step_name             STRING    NOT NULL COMMENT 'load_context | planner | plan_verifier | sql_compiler | sql_generator | sql_validator | run_query | result_checks | reviewer | answer | save_history',
  step_order            SMALLINT  NOT NULL,
  attempt               SMALLINT  NOT NULL COMMENT '1, or 2 for the single retry',
  status                STRING    NOT NULL COMMENT 'ok | failed | skipped',
  started_at            TIMESTAMP NOT NULL,
  ended_at              TIMESTAMP,
  duration_ms           INT,
  input_payload         STRING    COMMENT 'JSON, redacted, no raw result sets',
  output_payload        STRING    COMMENT 'JSON: plan, SQL, check results, LLM response',
  error_message         STRING,

  model_provider        STRING    COMMENT 'LLM steps only, e.g. aws-bedrock',
  model_name            STRING,
  prompt_version        STRING,
  temperature           DECIMAL(3,2),
  input_tokens          INT,
  output_tokens         INT,
  cache_read_tokens     INT,

  created_at            TIMESTAMP NOT NULL,
  CONSTRAINT pk_finance_chat_message_events PRIMARY KEY (event_id)
)
USING DELTA
CLUSTER BY (message_id, step_order)
COMMENT 'One row per graph step per question, for audit and debugging'
TBLPROPERTIES (
  'delta.autoOptimize.optimizeWrite' = 'true',
  'delta.autoOptimize.autoCompact'   = 'true'
);

ALTER TABLE lakehouse_mvpai.aiops.finance_chat_message_events
  ADD CONSTRAINT chk_evt_status CHECK (status IN ('ok', 'failed', 'skipped'));

-- ---------------------------------------------------------------------------
-- 4. Message feedback: like / dislike, reason, and the answer the user expected
--    One row per feedback action. If a user changes their mind, add a new row and
--    set is_current = false on the old one (the app does both in one MERGE).
--    The review_* columns are for the later evaluation page and can stay empty for now.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS lakehouse_mvpai.aiops.finance_chat_message_feedback (
  feedback_id           STRING    NOT NULL COMMENT 'UUID',
  message_id            STRING    NOT NULL COMMENT 'Refers to finance_chat_messages (the answer being rated)',
  conversation_id       STRING    NOT NULL,
  user_id               STRING    NOT NULL COMMENT 'Who gave the feedback',
  rating                SMALLINT  NOT NULL COMMENT '1 = like, -1 = dislike',
  reason_code           STRING    COMMENT 'wrong_number | wrong_kpi | wrong_filter | missing_data | unclear | too_slow | other',
  comment               STRING    COMMENT 'Free text from the user',
  expected_answer       STRING    COMMENT 'The answer the user says they wanted (evaluation page, later)',
  is_current            BOOLEAN   NOT NULL COMMENT 'true for the latest feedback of this user on this message',

  review_status         STRING    NOT NULL COMMENT 'new | in_review | accepted | rejected | fixed',
  reviewed_by           STRING,
  reviewed_at           TIMESTAMP,
  review_note           STRING,
  eval_case_id          STRING    COMMENT 'Set when this feedback is promoted to a golden test case',

  created_at            TIMESTAMP NOT NULL,
  updated_at            TIMESTAMP NOT NULL,
  CONSTRAINT pk_finance_chat_message_feedback PRIMARY KEY (feedback_id)
)
USING DELTA
CLUSTER BY (message_id, created_at)
COMMENT 'Like and dislike feedback on answers, plus review state for the evaluation page'
TBLPROPERTIES (
  'delta.autoOptimize.optimizeWrite' = 'true',
  'delta.autoOptimize.autoCompact'   = 'true'
);

ALTER TABLE lakehouse_mvpai.aiops.finance_chat_message_feedback
  ADD CONSTRAINT chk_fb_rating CHECK (rating IN (-1, 1));
ALTER TABLE lakehouse_mvpai.aiops.finance_chat_message_feedback
  ADD CONSTRAINT chk_fb_reason CHECK (reason_code IS NULL OR reason_code IN
    ('wrong_number', 'wrong_kpi', 'wrong_filter', 'missing_data', 'unclear', 'too_slow', 'other'));
ALTER TABLE lakehouse_mvpai.aiops.finance_chat_message_feedback
  ADD CONSTRAINT chk_fb_review CHECK (review_status IN ('new', 'in_review', 'accepted', 'rejected', 'fixed'));

-- ---------------------------------------------------------------------------
-- 5. User memory: compact profile from the user's last 30 questions
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS lakehouse_mvpai.aiops.finance_chat_user_memory (
  user_id               STRING    NOT NULL,
  frequent_kpis         STRING    COMMENT 'JSON: [{"kpi_id": "...", "count": 7}]',
  frequent_entities     STRING    COMMENT 'JSON: [{"entity": "101", "count": 5}]',
  default_entity        STRING    COMMENT 'Applied only when the user omits an entity and has a clear habit',
  default_period        STRING,
  recent_window_size    SMALLINT  NOT NULL COMMENT 'Normally 30',
  updated_at            TIMESTAMP NOT NULL,
  CONSTRAINT pk_finance_chat_user_memory PRIMARY KEY (user_id)
)
USING DELTA
COMMENT 'One row per user';

-- ---------------------------------------------------------------------------
-- Typical reads
-- ---------------------------------------------------------------------------
-- Chat UI: current like/dislike of a message:
--   SELECT rating FROM lakehouse_mvpai.aiops.finance_chat_message_feedback
--    WHERE message_id = :mid AND user_id = :uid AND is_current = true;
-- Evaluation page: disliked answers waiting for review:
--   SELECT f.*, m.question_text, m.answer_text, m.sql_text, m.kpi_ids
--     FROM lakehouse_mvpai.aiops.finance_chat_message_feedback f
--     JOIN lakehouse_mvpai.aiops.finance_chat_messages m USING (message_id)
--    WHERE f.is_current = true AND f.rating = -1 AND f.review_status = 'new';
-- Follow-up context (Load context step):
--   SELECT summary, summary_through_turn FROM lakehouse_mvpai.aiops.finance_chat_conversations WHERE conversation_id = :cid;
--   SELECT turn_index, standalone_question, kpi_ids, plan, left(answer_text, 400) AS answer_start
--     FROM lakehouse_mvpai.aiops.finance_chat_messages
--    WHERE conversation_id = :cid AND visibility = 'visible' AND status IN ('answered', 'clarification')
--    ORDER BY turn_index DESC LIMIT 5;
-- Last 30 questions for a user (memory worker):
--   SELECT message_id, standalone_question, kpi_ids, plan, created_at
--     FROM lakehouse_mvpai.aiops.finance_chat_messages
--    WHERE user_id = :uid AND visibility = 'visible' AND status = 'answered'
--    ORDER BY created_at DESC LIMIT 30;
